  FT["SG-H3447"] = {"id":"SG-H3447","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/RELA1983-S596-2006?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Order under Section 11(3)","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation RELA1983-S596-2006","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 1 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3447-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Revised Edition of the Laws Act\n(Chapter 275)\nOrder under Section 11 (3)\nWhereas pursuant to section 10 of the Revised Edition of the Laws Act, the Law Revision Commissioners have published in loose-leaf form the Companies Act (Chapter 50) as in force on 1st October 2006:\nAnd Whereas it is provided under section 11(3) of the Revised Edition of the Laws Act that the Commissioners shall transmit to the President a copy of the loose-leaf edition of the Companies Act and the President may thereupon, by order published in the Gazette, specify that the loose-leaf edition of the Companies Act shall, in all courts and for all purposes, be the sole and only proper law of Singapore in respect of that Act:\nNow therefore it is hereby ordered by the President that the loose-leaf edition of the Companies Act shall, with effect from 31st October 2006, be the sole and only proper law of Singapore in respect of that Act."}}],"pack":"sg-p43"};
